// El uso del modelo vive en los datos de ejecucion, no en los items del turno:
//   runData['<nodo del modelo>'][0].data.ai_languageModel[0][0].json.tokenUsage
// Por eso el nodo `Medir el turno` del Cerebro lo deja en null y lo documenta.
// Aqui se lee desde fuera, despues del turno, y se devuelve al mismo
// execution_id. Requiere la migracion 246: antes de ella la rama
// ON CONFLICT DO UPDATE no tocaba estos campos y la escritura se perdia EN
// SILENCIO.
//
// Se suman TODAS las llamadas al modelo del turno (el agente puede llamar
// varias veces si usa herramientas), y se cuentan en model_calls.
const salida = [];

for (const item of $input.all()) {
  const j = item.json || {};
  const id = String(j.id ?? '');
  if (!id) continue;

  const runData = j?.data?.resultData?.runData;
  if (!runData) continue;  // ejecucion purgada o sin datos: se omite, no se inventa

  let prompt = 0, completion = 0, llamadas = 0;

  for (const corridas of Object.values(runData)) {
    for (const corrida of (corridas || [])) {
      const ramas = corrida?.data?.ai_languageModel;
      if (!Array.isArray(ramas)) continue;
      for (const rama of ramas) {
        for (const salidaModelo of (rama || [])) {
          const u = salidaModelo?.json?.tokenUsage;
          if (!u) continue;
          prompt += Number(u.promptTokens || 0);
          completion += Number(u.completionTokens || 0);
          llamadas += 1;
        }
      }
    }
  }

  // Sin ninguna llamada medida no se escribe nada: un 0 seria una medicion
  // inventada y la columna debe poder distinguir "no medido" de "cero".
  if (llamadas === 0) continue;

  salida.push({
    json: {
      execution_id: id,
      datos: {
        model_calls: llamadas,
        prompt_tokens: prompt,
        completion_tokens: completion,
      },
    },
  });
}

return salida;
